<?php if(!$serviceRows): ?><p class="empty-state">Bu bölümde hizmet bulunmuyor.</p><?php else: ?><div class="customer-service-grid"><?php foreach($serviceRows as $item): ?><article class="customer-service-card"><?php if($item['image_path']??null): ?><img class="service-cover" src="<?= e(url($item['image_path'])) ?>" alt="<?= e($item['name']) ?>" loading="lazy"><?php else: ?><div class="service-symbol"><i class="bi bi-stars" aria-hidden="true"></i><span><?= e($item['category']??'Kişisel bakım') ?></span></div><?php endif ?><div class="service-copy"><p class="eyebrow"><?= e($item['category']??'') ?></p><h3><?= e($item['name']) ?></h3><p><?= e($item['description']??'') ?></p><div class="service-meta"><strong><?= e($money($item['price'])) ?></strong><span><?= (int)$item['duration_minutes'] ?> dakika</span></div><div class="d-flex flex-wrap gap-2 mt-3"><?php if($item['is_active']): ?><a class="btn btn-lumera" href="<?= e(url('customer/book?step=2&service_id='.$item['id'])) ?>">Hizmeti seç</a><?php else: ?><span class="muted">Bu hizmet şu anda randevuya kapalı.</span><?php endif ?>
<form action="<?= e(url('customer/favorites/save')) ?>" method="post"><?= App\Core\Csrf::field() ?><input type="hidden" name="service_id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="add" value="<?= in_array((int)$item['id'],$favoriteIds??[],true)?'0':'1' ?>"><button class="btn btn-outline-dark" type="submit" aria-label="<?= e($item['name']) ?> <?= in_array((int)$item['id'],$favoriteIds??[],true)?'favorilerden çıkar':'favorilere ekle' ?>"><i class="bi <?= in_array((int)$item['id'],$favoriteIds??[],true)?'bi-heart-fill':'bi-heart' ?>" aria-hidden="true"></i></button></form></div></div></article><?php endforeach ?></div><?php endif ?>
